            messageHeaderMock.Setup(m => m.Get("PROFILE_RANK")).Returns(rankLabelMock.Object);
            messageHeaderMock.Setup(m => m.Get("GAME_ADMIN")).Returns(adminContainerMock.Object);
            adminContainerMock.Setup(a => a.Get<LabelWidget>("LABEL")).Returns(adminLabelMock.Object);
            adminLabelMock.Setup(a => a.GetText).Returns(() => "Admin");
            adminLabelMock.Setup(a => a.Bounds).Returns(new Bounds { Height = 10, Width = 50, Left = 5 });
            nameLabelMock.Setup(n => n.GetText).Returns(() => "TestPlayer");
