            headerMock.Setup(h => h.Bounds).Returns(new Bounds { Width = 300, Height = 20 });
            badgeContainerMock.Setup(b => b.Bounds).Returns(new Bounds { Width = 300, Height = 0, Y = 0 });
            badgeContainerMock.Setup(b => b.IsVisible).Returns(() => false);
            widgetMock.Setup(w => w.Bounds).Returns(new Bounds { Width = 300, Height = 20 });
            widgetMock.Setup(w => w.Get("HEADER")).Returns(headerMock.Object);
