            widgetMock.Setup(w => w.Bounds).Returns(new Bounds { Width = 300, Height = 20 });
            // Setup ModData to return a PlayerDatabase with a profile URL
            var playerDatabaseMock = new Mock<PlayerDatabase>();
            playerDatabaseMock.Setup(p => p.Profile).Returns("http://testprofile/");
            modDataMock.Setup(m => m.GetOrCreate<PlayerDatabase>()).Returns(playerDatabaseMock.Object);
            // Setup client
            clientMock.Setup(c => c.Fingerprint).Returns("fingerprint");
            clientMock.Setup(c => c.IsAdmin).Returns(true);
            // Setup HttpClient with mocked response
            var handlerMock = new Mock<HttpMessageHandler>();
            var responseContent = new StringContent(@"
Player:
  ProfileName: TestPlayer
  ProfileRank: General
");
